static std::span<const OperandInfo> operandInfosOf(TerminatorKind kind)
{
    switch (kind) {
    case TerminatorKind::Branch: case TerminatorKind::TestAndBranch:
        return operandInfos200;
    case TerminatorKind::Switch: case TerminatorKind::SwitchString:
        return operandInfos201;
    case TerminatorKind::Return:
        return operandInfos202;
    case TerminatorKind::ReturnCall:
        return operandInfos203;
    case TerminatorKind::Throw:
        return operandInfos67;
    case TerminatorKind::Rethrow:
        return operandInfos204;
    case TerminatorKind::SwitchOnShape:
        return operandInfos205;
    case TerminatorKind::TryCallInline:
        return operandInfos123;
    default:
        return { };
    }
}

const OperandInfo& operandInfoOf(Opcode opcode, uint32_t operandIndex)
{
    std::span<const OperandInfo> infos = operandInfosOf(opcode);
    RELEASE_ASSERT(operandIndex < infos.size() || (!infos.empty() && infos.back().isVariadic));
    return infos[std::min<size_t>(operandIndex, infos.size() - 1)];
}

const OperandInfo& operandInfoOf(TerminatorKind kind, uint32_t operandIndex)
{
    std::span<const OperandInfo> infos = operandInfosOf(kind);
    RELEASE_ASSERT(operandIndex < infos.size() || (!infos.empty() && infos.back().isVariadic));
    return infos[std::min<size_t>(operandIndex, infos.size() - 1)];
}

